<?php require 'app.php';need_school(['director','dos']);$sid=school_id();$id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT * FROM students WHERE id=? AND school_id=?');$q->execute([$id,$sid]);$st=$q->fetch();if(!$st){http_response_code(404);exit('Student not found.');}$q=db()->prepare('SELECT id,name,stream FROM classes WHERE school_id=? ORDER BY name,stream');$q->execute([$sid]);$classes=$q->fetchAll();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$photo=cloud_upload('photo')?:$st['photo_url'];$q=db()->prepare('UPDATE students SET class_id=?,admission_number=?,first_name=?,last_name=?,gender=?,date_of_birth=?,photo_url=? WHERE id=? AND school_id=?');$q->execute([$_POST['class_id']?:null,trim($_POST['admission_number']),trim($_POST['first_name']),trim($_POST['last_name']),$_POST['gender'],$_POST['dob']?:null,$photo,$id,$sid]);audit_log('student.updated',['student_id'=>$id]);$msg='Student details updated.';$q=db()->prepare('SELECT * FROM students WHERE id=? AND school_id=?');$q->execute([$id,$sid]);$st=$q->fetch();}catch(Throwable $e){$msg=$e->getMessage();}}ob_start();?><div class="panel"><p><?=h($msg)?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid"><label>Admission number<input name="admission_number" value="<?=h($st['admission_number'])?>" required></label><label>First name<input name="first_name" value="<?=h($st['first_name'])?>" required></label><label>Last name<input name="last_name" value="<?=h($st['last_name'])?>" required></label><label>Gender<select name="gender"><?php foreach(['not_stated','female','male','other'] as $g):?><option <?=$st['gender']===$g?'selected':''?> value="<?=$g?>"><?=$g?></option><?php endforeach;?></select></label><label>Date of birth<input type="date" name="dob" value="<?=h($st['date_of_birth'])?>"></label><label>Class<select name="class_id"><option value="">Unassigned</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$st['class_id']==$c['id']?'selected':''?>><?=h($c['name'].' '.$c['stream'])?></option><?php endforeach;?></select></label><label>Replace photo<input type="file" name="photo" accept="image/*"></label></div><button>Update student</button></form></div><?php page('Edit Student',ob_get_clean());
